package com.nvv.mediadata.data.module.utilsimport android.content.Contextimport android.os.Buildimport androidx.compose.animation.core.FastOutSlowInEasingimport androidx.compose.animation.core.animateFloatimport androidx.compose.animation.core.infiniteRepeatableimport androidx.compose.animation.core.rememberInfiniteTransitionimport androidx.compose.animation.core.tweenimport androidx.compose.foundation.layout.Boximport androidx.compose.foundation.layout.fillMaxSizeimport androidx.compose.runtime.Composableimport androidx.compose.runtime.getValueimport androidx.compose.runtime.rememberimport androidx.compose.ui.Alignmentimport androidx.compose.ui.Modifierimport androidx.compose.ui.draw.drawWithCacheimport androidx.compose.ui.geometry.CornerRadiusimport androidx.compose.ui.geometry.Offsetimport androidx.compose.ui.graphics.Brushimport androidx.compose.ui.graphics.Colorimport androidx.compose.ui.layout.ContentScaleimport androidx.compose.ui.platform.LocalContextimport androidx.compose.ui.unit.Dpimport androidx.compose.ui.unit.dpimport coil3.ImageLoaderimport coil3.compose.SubcomposeAsyncImageimport coil3.gif.AnimatedImageDecoderimport coil3.gif.GifDecoderimport coil3.request.CachePolicyimport coil3.request.ImageRequestimport coil3.request.allowHardwareimport coil3.request.crossfadeimport timber.log.Timberobject SingletonImageLoader {	private var instance: ImageLoader? = null	fun getInstance(context: Context): ImageLoader {		return instance ?: synchronized(this) {			instance ?: ImageLoader.Builder(context)				.components {					if (Build.VERSION.SDK_INT >= 28) {						add(AnimatedImageDecoder.Factory())					} else {						add(GifDecoder.Factory())					}				}.build().also { instance = it }		}	}}@Composablefun Modifier.shimmer(cornerRadius: Dp = 0.dp): Modifier {	val shimmerColors = listOf(		Color.DarkGray.copy(alpha = 0.4f),		Color.White.copy(alpha = 0.6f),		Color.LightGray.copy(alpha = 0.3f)	)	val transition = rememberInfiniteTransition(label = "Shimmer")	val translateAnim by transition.animateFloat(		initialValue = -400f,		targetValue = 1200f,		animationSpec = infiniteRepeatable(			animation = tween(				durationMillis = 1600,				easing = FastOutSlowInEasing			)		),		label = "Translate"	)	return this.drawWithCache {		val brush = Brush.linearGradient(			colors = shimmerColors,			start = Offset(translateAnim, 0f),			end = Offset(translateAnim + size.width / 1.5f, size.height)		)		val cornerPx = cornerRadius.toPx()		onDrawWithContent {			drawRoundRect(				brush = brush,				cornerRadius = CornerRadius(cornerPx, cornerPx),				size = size			)		}	}}@Composablefun PictureWithAnimated(	modifier: Modifier = Modifier,	url: String, contentDescription: String = "",	contentScale: ContentScale = ContentScale.Crop,	alignment: Alignment = Alignment.Center,	enableAnimated: Boolean = true,	onError: () -> Unit = {},) {	val context = LocalContext.current	val imageLoader = remember { SingletonImageLoader.getInstance(context) }	val imageRequest = ImageRequest.Builder(context)		.data(url)		.memoryCacheKey(url)		.diskCacheKey(url)		.diskCachePolicy(CachePolicy.ENABLED)		.memoryCachePolicy(CachePolicy.ENABLED)		.crossfade(true)		.crossfade(1000)		.allowHardware(true)		.build()	SubcomposeAsyncImage(		model = imageRequest,		imageLoader = imageLoader,		contentDescription = contentDescription,		contentScale = contentScale,		modifier = modifier,		alignment = alignment,		loading = {			if (enableAnimated) {				Box(					modifier = Modifier						.fillMaxSize()						.shimmer()				)			}		},		error = { state ->			onError()		}	)}